<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\UserConsentedScopesUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserConsentedScopesUserAccessor
{
    private UserConsentedScopesUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserConsentedScopesUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserConsentedScopesUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserConsentedScopesUserVO::from($user);
        return $copy;
    }
}
